  /* 11. L’excuse du destin */
  quiz: [
    { t: "« C’était écrit que je rate la prière : Allah l’a voulu. »", ok: false,
      pourquoi: "C’est utiliser le destin pour justifier une faute. Tu ne connaissais pas l’écrit avant d’agir : tu as suivi ta paresse. Le Prophète ﷺ a qualifié de « dispute » une parole semblable de ‘Alî.", ev: ["h-alifatima", "q6-148-149"] },
    { t: "« Mon père est mort : c’est le décret d’Allah. Innâ lillâh wa innâ ilayhi râji‘ûn. »", ok: true,
      pourquoi: "Invoquer le destin face à un malheur est exactement ce qu’il faut faire : c’est la parole des endurants.", ev: ["q2-155-157", "q57-22-23"] },
    { t: "« Si Allah voulait que j’arrête ce péché, Il m’aurait déjà guidé. »", ok: false,
      pourquoi: "C’est l’argument des polythéistes réfuté par le Coran. Allah guide celui qui lutte pour Lui et ne change pas ton état tant que tu ne changes pas ce qui est en toi.", ev: ["q6-148-149", "q29-69", "q13-11"] },
    { t: "« Je ne me soigne pas : si ma guérison est écrite, elle viendra. »", ok: false,
      pourquoi: "Le remède fait partie du décret. Le Prophète ﷺ a dit que chaque maladie a un remède, et ‘Umar a fui l’épidémie « du décret d’Allah vers le décret d’Allah ».", ev: ["h-remede", "h-peste"] },
    { t: "« J’ai raté mon permis : qaddara Allâh. Je vais m’entraîner et le repasser. »", ok: true,
      pourquoi: "Accepter le passé sans « si seulement », puis reprendre l’effort pour l’avenir : c’est le hadith du croyant fort.", ev: ["h-fort"] },
    { t: "« Si seulement j’avais pris l’autre route, l’accident ne serait pas arrivé. »", ok: false,
      pourquoi: "Ce « si » conteste un décret accompli : il ouvre la porte au Shaytân et laisse un regret dans le cœur. Tirer une leçon de prudence pour l’avenir, en revanche, est utile.", ev: ["h-fort", "q3-156"] },
    { t: "« Adam s’est justifié par le destin face à Moïse : je peux faire pareil pour mes péchés. »", ok: false,
      pourquoi: "Adam s’était déjà repenti et Allah l’avait pardonné. Il a invoqué le destin pour le malheur (la sortie du Paradis), pas pour justifier la faute.", ev: ["h-adam", "q2-37", "s-regle"] },
    { t: "« Je ne cherche pas de travail : ma subsistance est écrite. »", ok: false,
      pourquoi: "La subsistance est écrite avec ses causes. Allah ordonne de parcourir la terre et de chercher Sa grâce ; les oiseaux sortent le matin.", ev: ["q67-15", "q62-10", "h-oiseaux"] },
    { t: "« J’ai péché, je me suis repenti ; je me console en sachant qu’Allah l’avait décrété. »", ok: true,
      pourquoi: "Après le repentir, la faute devient pour toi un événement passé : t’en consoler par le destin est permis, comme l’a fait Adam.", ev: ["h-adam", "s-regle", "q39-53"] },
    { t: "« Mon destin est écrit, donc je n’ai pas vraiment de choix. »", ok: false,
      pourquoi: "Allah t’a reconnu une volonté réelle et te jugera sur elle. L’écrit décrit ce que tu choisiras ; il ne choisit pas à ta place.", ev: ["q18-29", "q81-28-29", "q76-3"] }
  ],

