    { nom: "Ibrâhîm", ar: "إِبْرَاهِيم", decret: "Jeté dans le feu par son peuple.", fait: "Il dit : « Allah nous suffit, et quel excellent Garant. »", lecon: "Quand tous les moyens sont épuisés, le cœur s’appuie sur Allah seul.", verbes: ["dua"], ev: ["h-hasbuna", "q3-173"] },
    { nom: "Ya‘qûb", ar: "يَعْقُوب", decret: "La perte de Yûsuf, puis de son frère.", fait: "Il prit des précautions, patienta d’une belle patience, se plaignit à Allah seul et envoya ses fils enquêter.", lecon: "Patience, précaution et espoir actif vont ensemble.", verbes: ["effort", "dua", "accueil"], ev: ["q12-18", "q12-67-68", "q12-83", "q12-86", "q12-87"] },
    { nom: "Yûsuf", ar: "يُوسُف", decret: "Le puits, l’esclavage, la prison.", fait: "Il resta pieux et patient, et vit à la fin la douceur d’Allah dans chaque étape.", lecon: "« Quiconque craint Allah et patiente » : la récompense n’est jamais perdue.", verbes: ["accueil", "effort"], ev: ["q12-90", "q12-100", "q12-21"] },
    { nom: "Ayyûb", ar: "أَيُّوب", decret: "La maladie, la perte de ses biens et de sa famille.", fait: "Il invoqua sans se révolter, puis frappa la terre de son pied comme Allah le lui demandait.", lecon: "Même la guérison passe par un geste : la cause fait partie de la délivrance.", verbes: ["accueil", "dua", "effort"], ev: ["q21-83-84", "q38-41-44"] },
    { nom: "Yûnus", ar: "يُونُس", decret: "Le ventre du poisson, dans les ténèbres.", fait: "Il reconnut sa faute et glorifia Allah.", lecon: "Sa glorification fut la cause de sa délivrance.", verbes: ["tawba", "dua"], ev: ["q21-87-88", "q37-143-144"] },
    { nom: "Maryam", ar: "مَرْيَم", decret: "L’accouchement, seule, épuisée.", fait: "Allah lui demanda de secouer le tronc du palmier.", lecon: "Une femme épuisée ne peut pas faire tomber des dattes : Allah lui demande quand même le geste.", verbes: ["effort", "accueil"], ev: ["q19-23-26"] },
    { nom: "Mûsâ et al-Khidr", ar: "مُوسَى وَالخَضِر", decret: "Un bateau abîmé, un garçon tué, un mur relevé sans salaire.", fait: "Mûsâ n’arriva pas à patienter, puis découvrit la sagesse de chaque événement.", lecon: "Derrière ce qui choque, une miséricorde que tu ne vois pas encore.", verbes: ["accueil"], ev: ["q18-79-82", "q2-216"] },
    { nom: "Muhammad ﷺ", ar: "مُحَمَّد ﷺ", decret: "L’exil, la guerre, la mort de son fils.", fait: "Il prépara l’Hégire avec soin, porta deux cottes de mailles à Uhud, pleura son fils sans révolte.", lecon: "Le modèle complet : les moyens, la confiance et la patience, ensemble.", verbes: ["effort", "dua", "accueil"], ev: ["q9-40", "h-dirayn", "h-larmes"] }
